import urllib.request, ssl, os
os.chdir("$D")
ctx = ssl.create_default_context(); ctx.check_hostname=False; ctx.verify_mode=ssl.CERT_NONE
def get(url):
    req = urllib.request.Request(url, headers={'User-Agent':'Mozilla/5.0'})
    return urllib.request.urlopen(req, context=ctx, timeout=20).read()

vids = {
 'JGAG_1':'fm7qxI3gmpw', 'JGAG_2':'9AKf06lP2Gk', 'JGAG_3':'WMW1pjzEhfY',
 'LEG_1':'00lyd5_Epuw', 'LEG_2':'zdkd56d4vyo', 'LEG_3':'JYQWRdu2U2g',
}
for tag, vid in vids.items():
    ok = []
    for L in ('L3','L2','L1'):
        for n in range(6):
            try:
                d = get(f'https://i.ytimg.com/sb/{vid}/storyboard3_{L}/M{n}.jpg')
                open(f'sb_{tag}_{L}_{n}.jpg','wb').write(d); ok.append((L,n,len(d)))
            except Exception:
                break
        if ok: break
    # preview frame thumbs as backup
    for p in ('1','2','3'):
        try:
            d = get(f'https://i.ytimg.com/vi/{vid}/hq{p}.jpg')
            open(f'hq_{tag}_{p}.jpg','wb').write(d)
        except Exception: pass
    print(tag, vid, 'storyboards:', ok[:6])
EOF

